import{_ as a,a as l,b as n,c as o}from"./chunks/5_cssJsExec_20200103141756.CWqdowcH.js";import{_ as e,o as p,c as t,a0 as r}from"./chunks/framework.DqMqoJl9.js";const E=JSON.parse('{"title":"渲染优化","description":"","frontmatter":{},"headers":[],"relativePath":"performance/2-paint.md","filePath":"performance/2-paint.md","lastUpdated":1791573371000}'),i={name:"performance/2-paint.md"};function c(y,s,d,u,h,b){return p(),t("div",null,[...s[0]||(s[0]=[r('<h1 id="渲染优化" tabindex="-1">渲染优化 <a class="header-anchor" href="#渲染优化" aria-label="Permalink to &quot;渲染优化&quot;">​</a></h1><h2 id="_1-浏览器渲染过程" tabindex="-1">1 浏览器渲染过程 <a class="header-anchor" href="#_1-浏览器渲染过程" aria-label="Permalink to &quot;1 浏览器渲染过程&quot;">​</a></h2><p><img src="'+a+`" alt=""></p><ol><li>解析 HTML 生成 DOM 树</li><li>解析 CSS 生成 CSSOM 规则树</li><li>将 DOM 树与 CSSOM 规则树合并在一起生成渲染树</li><li>遍历渲染树开始布局，计算每个节点的位置大小信息</li><li>将渲染树每个节点绘制到屏幕</li></ol><p>这五个步骤并不一定一次性顺序完成。如果 DOM 或 CSSOM 被修改，以上过程需要重复执行，这样才能计算出哪些像素需要在屏幕上进行重新渲染。实际页面中，CSS 与 JavaScript 往往会多次修改 DOM 和 CSSOM</p><h2 id="_2-重绘和回流" tabindex="-1">2 重绘和回流 <a class="header-anchor" href="#_2-重绘和回流" aria-label="Permalink to &quot;2 重绘和回流&quot;">​</a></h2><h3 id="_2-1-回流" tabindex="-1">2.1 回流 <a class="header-anchor" href="#_2-1-回流" aria-label="Permalink to &quot;2.1 回流&quot;">​</a></h3><ul><li>当 render tree 中的一部分（或全部）因为元素的规模尺寸、布局、隐藏等改变而需要重新构建。这就称为回流</li><li>当页面的布局和几何属性改变时，就需要回流</li></ul><p>会触发回流的 css 属性：</p><ul><li>盒子模型相关属性。width, height, padding, margin, display, border, min-height</li><li>定位属性和浮动。top, bottom, left, right, position, float, clear</li><li>改变节点内部文字结构。text-aligin, overflow, font-weight, font-family, line-height, vertival-aligin, font-size</li></ul><h3 id="_2-2-重绘" tabindex="-1">2.2 重绘 <a class="header-anchor" href="#_2-2-重绘" aria-label="Permalink to &quot;2.2 重绘&quot;">​</a></h3><ul><li>当 render tree 中的一些元素需要更新属性，而这些属性只是影响元素的外观，风格，而不会影响布局的，比如 <code>background-color</code>。这就称为重绘</li></ul><p><strong>回流一定会引起重绘，而重绘不一定会引起回流</strong></p><p>只触发重绘的 css 属性：</p><p>color, border-style, border-radius, visibility, text-decoration, background, background-image, background-position, background-repeat, background-size, outline-color, outline-style, box-shadow</p><h2 id="_3-复合线程与图层" tabindex="-1">3 复合线程与图层 <a class="header-anchor" href="#_3-复合线程与图层" aria-label="Permalink to &quot;3 复合线程与图层&quot;">​</a></h2><h3 id="_3-1-新建-dom-的过程" tabindex="-1">3.1 新建 DOM 的过程 <a class="header-anchor" href="#_3-1-新建-dom-的过程" aria-label="Permalink to &quot;3.1 新建 DOM 的过程&quot;">​</a></h3><ol><li>获取 DOM 后分割为多个图层</li><li>对每个图层的节点计算样式结果（recalculate style - 样式重计算）</li><li>为每个节点生成图形和位置（layout - 回流和重布局）</li><li>将每个节点绘制填充到图层位图中（paint - 重绘）</li><li>图层作为纹理上传到 GPU</li><li>合成多个图层到页面上生成最终屏幕图像（composite layers - 图层重组）</li></ol><blockquote><p>重绘和回流是以图层为单位的</p></blockquote><p>将频繁重绘回流的 DOM 元素单独作为一个独立图层，那么这个 DOM 元素的重绘和回流的影响只会在这个图层中。</p><p>但是图层并不是越多越好，图层的合成运算量是比较大的，如果图层太多的话就会在 composite layers 这里消耗大量的性能，这点也是需要极力避免的。</p><h3 id="_3-2-chrome-创建图层的条件" tabindex="-1">3.2 chrome 创建图层的条件 <a class="header-anchor" href="#_3-2-chrome-创建图层的条件" aria-label="Permalink to &quot;3.2 chrome 创建图层的条件&quot;">​</a></h3><ul><li>3D 或透视变换 CSS 属性（perspective transfrom）</li><li>使用加速视频解码的 video 节点 (浏览器会对 video 的每一帧进行重绘，所以能看到连续的视频)</li><li>拥有 3D (WebGl) 上下文或加速 2D 上下文的 canvas 节点</li><li>混合插件 (如 flash)</li><li>对自己的 opacity 做 CSS 动画或使用一个动画 webkit 变换的元素</li><li>拥有加速 CSS 过滤器的元素 (translate 3d)</li><li>元素拥有一个 z-index 较低且包含一个复合层的兄弟元素 (即有兄弟元素，有 z-index)</li></ul><p>gif 图会持续的触发重绘，但是不会创建新的图层</p><h2 id="_4-避免重绘" tabindex="-1">4 避免重绘 <a class="header-anchor" href="#_4-避免重绘" aria-label="Permalink to &quot;4 避免重绘&quot;">​</a></h2><ul><li>使用 translate 代替 top，top 会触发 layout 但 translate 不会</li><li>使用 opacity 代替 visibility，独立图层情况下，visibility 会触发重绘但是 opacity 不会</li><li>不要一条条修改 DOM 样式，预先定义好 class 然后修改 DOM 的 className，因为每修改一条样式都会触发重绘</li><li>把 DOM 离线后修改，display: none，后续修改都不会重绘</li><li>不要把 DOM 的属性值放在循环里，当成循环的变量。比如获取 offsetHeight 时，会触发回流。因为需要刷新缓冲区域，去获取真实的值</li><li>不要使用 table 布局，可能一个小改动会造成整个 table 的重新布局</li><li>动画实现速度的选择，UI 线程和 js 线程是相互阻塞的，css 动画会影响 js 运行</li><li>动画区域使用新图层</li><li>启动 GPU 硬件加速</li></ul><h2 id="_5-使用-fastdom" tabindex="-1">5 使用 FastDom <a class="header-anchor" href="#_5-使用-fastdom" aria-label="Permalink to &quot;5 使用 FastDom&quot;">​</a></h2><p>todo</p><p>在某些场景避免不了频繁的回流和重绘，比如 js 动画，就可能会造成布局抖动</p><p>布局抖动是因为有连续的读写 dom 属性的操作，造成了强制回流</p><p><strong>解决方案：</strong></p><ol><li>读写分离 (统一读取属性和修改属性)</li><li>使用 FastDom (FastDom 实现了读写分离)</li></ol><h2 id="_6-阻塞渲染" tabindex="-1">6 阻塞渲染 <a class="header-anchor" href="#_6-阻塞渲染" aria-label="Permalink to &quot;6 阻塞渲染&quot;">​</a></h2><h3 id="_6-1-验证-css-加载是否阻塞页面渲染" tabindex="-1">6.1 验证 CSS 加载是否阻塞页面渲染 <a class="header-anchor" href="#_6-1-验证-css-加载是否阻塞页面渲染" aria-label="Permalink to &quot;6.1 验证 CSS 加载是否阻塞页面渲染&quot;">​</a></h3><p>默认情况下，CSS 被视为阻塞渲染的资源，这意味着浏览器将不会渲染任何已处理的内容，直至 CSSOM 构建完毕。</p><p>CSSOM 构建时，JavaScript 执行将暂停，直至 CSSOM 就绪。</p><p>html 中有如下代码，css 放在两个 div 的中间：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;!</span><span style="color:#22863A;">DOCTYPE</span><span style="color:#6F42C1;"> html</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">html</span><span style="color:#6F42C1;"> lang</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;zh_CN&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">head</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">meta</span><span style="color:#6F42C1;"> charset</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;UTF-8&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">meta</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;viewport&quot;</span><span style="color:#6F42C1;"> content</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;width=device-width, initial-scale=1.0&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">title</span><span style="color:#24292E;">&gt;验证css加载是否影响页面渲染&lt;/</span><span style="color:#22863A;">title</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">head</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line1&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">link</span><span style="color:#6F42C1;"> href</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;./styles.css&quot;</span><span style="color:#6F42C1;"> rel</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;stylesheet&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line2&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">html</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>运行结果如下：</p><p><img src="`+l+`" alt=""></p><p>可以看到页面渲染了两次，第一次是在 html 加载完成，css 还未加载完成的时候，这时页面只渲染出了 line1，并且没有样式</p><p>第二次渲染是在 css 加载完成后，这时把 line1 line2 都渲染出来了，并且有样式</p><p><strong>结论：</strong></p><ul><li>页面渲染顺序执行</li><li>页面渲染不会等待 css js 都加载完成 (但是只会渲染一部分)</li><li>css 加载会阻塞页面的渲染 (css 后面的内容需要等待 css 加载完成才会渲染)</li></ul><h3 id="_6-2-验证-js-加载是否影响页面渲染" tabindex="-1">6.2 验证 js 加载是否影响页面渲染 <a class="header-anchor" href="#_6-2-验证-js-加载是否影响页面渲染" aria-label="Permalink to &quot;6.2 验证 js 加载是否影响页面渲染&quot;">​</a></h3><p>html 中有如下代码：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line1&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">script</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;./script.js&quot;</span><span style="color:#24292E;">&gt;&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line2&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>运行结果：</p><p><img src="`+n+`" alt=""></p><p><strong>结论：</strong></p><ul><li>js 加载会阻塞页面渲染，js 后面的内容在 js 加载完成前不会被渲染</li><li>js 运行会阻塞页面渲染，js 运行时页面不会被渲染，因为 js 可能会操作 dom 或者修改文档结构，不可能一边操作 dom 一边渲染</li><li>js 顺序执行，阻塞后续 js 的执行</li></ul><h3 id="_6-3-defer" tabindex="-1">6.3 defer <a class="header-anchor" href="#_6-3-defer" aria-label="Permalink to &quot;6.3 defer&quot;">​</a></h3><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line1&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">script</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;./script1.js&quot;</span><span style="color:#6F42C1;"> defer</span><span style="color:#24292E;">&gt;&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">script</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;./script2.js&quot;</span><span style="color:#6F42C1;"> defer</span><span style="color:#24292E;">&gt;&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text1&quot;</span><span style="color:#24292E;">&gt;line2&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>运行结果: 先渲染页面，然后执行 js，并且顺序执行</p><p><img src="`+o+'" alt=""></p><p><strong>结论：</strong></p><ul><li>async 与 defer 属性对于 inline-script 都是无效的</li><li>defer 属性表示延迟执行引入的 JavaScript，即这段 JavaScript 加载时 HTML 并未停止解析，这两个过程是并行的</li><li>defer 不会改变 script 中代码的执行顺序 (加了 defer 属性的 js) (没有加 defer 的 js 会阻塞并且先执行)</li></ul><h3 id="_6-4-async" tabindex="-1">6.4 async <a class="header-anchor" href="#_6-4-async" aria-label="Permalink to &quot;6.4 async&quot;">​</a></h3><ul><li>async 与 defer 的区别在于，如果已经加载好，就会开始执行</li><li>多个 async-script 的执行顺序是不确定的</li><li>向 document 动态添加 script 标签时，async 属性默认是 true</li></ul><h2 id="_7-高频事件防抖" tabindex="-1">7 高频事件防抖 <a class="header-anchor" href="#_7-高频事件防抖" aria-label="Permalink to &quot;7 高频事件防抖&quot;">​</a></h2><p>todo</p><p>在一些频繁触发的事件中可能会造成布局抖动 (卡顿)，比如 mousemove 事件</p><p>或者是实现 js 动画的时候</p><p>造成抖动的原因通常是过多的触发了一个操作，比如 js 动画中触发的帧数过多 (100 帧)，而实际不需要这么多帧数 (60 帧)</p><p><strong>解决方案：</strong></p><ul><li>使用 <code>requestAnimationFrame</code> 将帧数控制在合理范围</li></ul><h2 id="_8-react-时间调度实现" tabindex="-1">8 React 时间调度实现 <a class="header-anchor" href="#_8-react-时间调度实现" aria-label="Permalink to &quot;8 React 时间调度实现&quot;">​</a></h2>',67)])])}const q=e(i,[["render",c]]);export{E as __pageData,q as default};
